#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long count = 0;
    for (long long factor = 1; factor <= n; factor *= 10) {
        long long high = n / (factor * 10);
        long long current = n / factor % 10;
        long long low = n % factor;
        if (current == 0) {
            count += high * factor;
        } else if (current == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }
    }
    cout << count << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long count = 0;
        for (long factor = 1; factor <= n; factor *= 10) {
            long high = n / (factor * 10);
            long current = n / factor % 10;
            long low = n % factor;
            if (current == 0) {
                count += high * factor;
            } else if (current == 1) {
                count += high * factor + low + 1;
            } else {
                count += (high + 1) * factor;
            }
        }
        System.out.println(count);
    }
}
